llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Maraviroc, a P-gp substrate with moderate oral bioavailability, showed absolute oral bioavailability of 33% in healthy volunteers, which is above the 20% threshold and supports a high-F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Indinavir, another P-gp substrate, had systemic bioavailability of 60–65% in humans, well above the 20% threshold, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Garenoxacin, a carboxylic-acid-containing small molecule, showed absolute oral bioavailability of 92% in humans, demonstrating that acidic/zwitterionic drugs can achieve high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Levodopa, a polar zwitterionic amino-acid-like drug, had mean absolute bioavailability of 80.4% in fasted volunteers, supporting that polar/ionizable molecules can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ezetimibe showed oral bioavailability of 35–60% in humans, providing additional supportive evidence above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental evidence, with high assay-transfer scores, reports oral bioavailability values at or above 23%, mostly 33–92%, all above the 20% threshold. No affirmative evidence of low oral bioavailability was retrieved, so the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct oral bioavailability record for a cephalosporin with a tetrazolethiol 3-substituent was retrieved.",
    "All evidence comes from structurally unrelated drug classes; transfer relies on assay-transfer scores rather than direct chemical analogy.",
    "Potential query-specific absorption barriers, such as beta-lactam instability or transporter-mediated efflux, are not directly addressed by the retrieved evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

